    {
      "task": "find tnt",
      "description": "Player must navigate to and look at the TNT landmark on the east side of the scene",
      "rules": [
        {
          "type": "position_near_with_facing",
          "params": {
            "target": [5, 0, 3],
            "max_distance": 5,
            "facing_tolerance": 60
          }
        }
      ]
    },
    {
      "task": "find jack_o_lantern",
      "description": "Player must navigate to and look at the jack_o_lantern landmark on the west side of the scene",
      "rules": [
        {
          "type": "position_near_with_facing",
          "params": {
            "target": [-4, 0, 3],
            "max_distance": 5,
            "facing_tolerance": 60
          }
        }
      ]
    },
    {
      "task": "mine dead_tube_coral_block",
