        {
          "type": "inventory_has",
          "params": {
            "item": "dead_tube_coral_block",
            "min_count": 1
          }
        }
      ]
    },
    {
      "task": "Build a fence",
      "description": "Player must place at least 2 oak_fence blocks in the world (near the jack_o_lantern area or anywhere in the scene)",
      "rules": [
        {
          "type": "voxel_count_in_box",
          "params": {
